  const salt = Uint8Array.from(atob(saltB64), c => c.charCodeAt(0));

  // Derive key
  const passwordBytes = new TextEncoder().encode(masterPassword);
  const baseKey = await crypto.subtle.importKey(
    "raw", passwordBytes, "PBKDF2", false, ["deriveKey"],
  );
  const aesKey = await crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );

  // Helper: encode owner and name to a storage key
  function encodeKey(owner: string, name: string): string {
    const ownerB64 = btoa(String.fromCharCode(...new TextEncoder().encode(owner)))
      .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    const nameB64 = btoa(String.fromCharCode(...new TextEncoder().encode(name)))
      .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    return `${SECRET_PREFIX}${ownerB64}:${nameB64}`;
  }

  // Helper: decode name from a storage key
  function decodeName(key: string, owner: string): string | undefined {
    if (!key.startsWith(SECRET_PREFIX)) return undefined;
    const rest = key.slice(SECRET_PREFIX.length);
    const colonIdx = rest.indexOf(':');
    if (colonIdx === -1) return undefined;
    const ownerB64 = rest.slice(0, colonIdx);
    const nameB64 = rest.slice(colonIdx + 1);
    // Verify owner matches
    const expectedOwnerB64 = btoa(String.fromCharCode(...new TextEncoder().encode(owner)))
      .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    if (ownerB64 !== expectedOwnerB64) return undefined;
    try {
      return new TextDecoder().decode(
        Uint8Array.from(atob(nameB64), c => c.charCodeAt(0))
      );
    } catch {
      return undefined;
    }
  }

  // Helper: get owner prefix for listing
  function ownerPrefix(owner: string): string {
    const ownerB64 = btoa(String.fromCharCode(...new TextEncoder().encode(owner)))
      .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
    return `${SECRET_PREFIX}${ownerB64}:`;
  }

  async function put(owner: string, name: string, value: string): Promise<void> {
    const key = encodeKey(owner, name);
    const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));
    const aad = new TextEncoder().encode(key);
    const plaintext = new TextEncoder().encode(value);
    const ciphertext = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv, additionalData: aad },
      aesKey,
      plaintext,
    );
    // Prepend IV to ciphertext
    const combined = new Uint8Array(IV_LENGTH + ciphertext.byteLength);
    combined.set(iv, 0);
    combined.set(new Uint8Array(ciphertext), IV_LENGTH);
    // Store as base64
    const stored = btoa(String.fromCharCode(...combined));
    await storage.set(key, stored);
  }

  async function get(owner: string, name: string): Promise<string | undefined> {
    const key = encodeKey(owner, name);
    const stored = await storage.get(key);
    if (stored === undefined) return undefined;
    try {
      const data = Uint8Array.from(atob(stored), c => c.charCodeAt(0));
      const iv = data.slice(0, IV_LENGTH);
      const ciphertext = data.slice(IV_LENGTH);
      const aad = new TextEncoder().encode(key);
      const plaintext = await crypto.subtle.decrypt(
        { name: "AES-GCM", iv, additionalData: aad },
        aesKey,
        ciphertext,
      );
      return new TextDecoder().decode(plaintext);
    } catch {
      throw new Error("Failed to decrypt secret: possible tampering detected");
    }
  }

  async function list(owner: string): Promise<string[]> {
    const prefix = ownerPrefix(owner);
    const allKeys = await storage.keys();
    const names: string[] = [];
    for (const key of allKeys) {
      const decoded = decodeName(key, owner);
      if (decoded !== undefined) {
        names.push(decoded);
      }
    }
    names.sort();
    return names;
  }

  async function remove(owner: string, name: string): Promise<boolean> {
    const key = encodeKey(owner, name);
    const stored = await storage.get(key);
    if (stored === undefined) return false;
    await storage.delete(key);
    return true;
  }

  return { put, get, list, remove };
}
