    "raw", passwordBytes, { name: "PBKDF2" }, false, ["deriveKey"],
  );
  const aesKey = await crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations: PBKDF2_ITERATIONS, hash: "SHA-256" },
    pbkdf2Key,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );

  function bytesToBase64(bytes: Uint8Array): string {
    let binary = "";
    for (let i = 0; i < bytes.length; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function base64ToBytes(b64: string): Uint8Array {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(0);
    }
    return bytes;
  }

  function base64UrlEncode(bytes: Uint8Array): string {
    return bytesToBase64(bytes).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }

  function base64UrlDecode(b64url: string): Uint8Array {
    let b64 = b64url.replace(/-/g, "+").replace(/_/g, "/");
    while (b64.length % 4) b64 += "=";
    return base64ToBytes(b64);
  }

  function encodeStorageKey(owner: string, name: string): string {
    const ownerB64 = base64UrlEncode(new TextEncoder().encode(owner));
    const nameB64 = base64UrlEncode(new TextEncoder().encode(name));
    return `${SECRET_PREFIX}${ownerB64}:${nameB64}`;
  }

  function ownerKeyPrefix(owner: string): string {
    const ownerB64 = base64UrlEncode(new TextEncoder().encode(owner));
    return `${SECRET_PREFIX}${ownerB64}:`;
  }

  async function put(owner: string, name: string, value: string): Promise<void> {
    const key = encodeStorageKey(owner, name);
    const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));
    const aad = new TextEncoder().encode(key);
    const plaintext = new TextEncoder().encode(value);
    const ciphertext = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv, additionalData: aad },
      aesKey,
      plaintext,
    );
    // Combine IV + ciphertext (which includes the GCM tag)
    const combined = new Uint8Array(IV_LENGTH + ciphertext.byteLength);
    combined.set(iv, 0);
    combined.set(new Uint8Array(ciphertext), IV_LENGTH);
    await storage.set(key, bytesToBase64(combined));
  }

  async function get(owner: string, name: string): Promise<string | undefined> {
    const key = encodeStorageKey(owner, name);
    const stored = await storage.get(key);
    if (stored === undefined) return undefined;
    try {
      const data = base64ToBytes(stored);
      if (data.length < IV_LENGTH + 16) throw new Error("Invalid data");
      const iv = data.slice(0, IV_LENGTH);
      const ciphertext = data.slice(IV_LENGTH);
      const aad = new TextEncoder().encode(key);
      const plaintext = await crypto.subtle.decrypt(
        { name: "AES-GCM", iv, additionalData: aad },
        aesKey,
        ciphertext,
      );
      return new TextDecoder().decode(plaintext);
    } catch (e) {
      if (e instanceof Error && e.message === "Invalid data") throw e;
      throw new Error("Decryption failed: possible tampering detected");
    }
  }

  async function list(owner: string): Promise<string[]> {
    const prefix = ownerKeyPrefix(owner);
    const allKeys = await storage.keys();
    const names: string[] = [];
    for (const key of allKeys) {
      if (!key.startsWith(prefix)) continue;
      const nameB64 = key.slice(prefix.length);
      try {
        const nameBytes = base64UrlDecode(nameB64);
        const name = new TextDecoder().decode(nameBytes);
        // Verify round-trip: re-encode and check
        if (base64UrlEncode(new TextEncoder().encode(name)) === nameB64) {
          names.push(name);
        }
      } catch {
        // Skip malformed keys
      }
    }
    names.sort();
    return names;
  }

  async function remove(owner: string, name: string): Promise<boolean> {
    const key = encodeStorageKey(owner, name);
    const existing = await storage.get(key);
    if (existing === undefined) return false;
    await storage.delete(key);
    return true;
  }

  return { put, get, list, remove };
}
